package com.bank.cache;

import java.util.logging.*;

public class CacheDemo {
    private static final Logger log = Logger.getLogger("Cache");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Database db = new Database();
        db.save("balance:SAV2001", "1000000");
        db.save("balance:CUR3001", "250000");
        db.save("fd:rate", "7.5");

        CacheService cache = new CacheService(db, 2); // cache capacity 2 per node
        // Which node owns each key?
        log.info(() -> "balance:SAV2001 -> " + cache.nodeFor("balance:SAV2001"));
        log.info(() -> "fd:rate -> " + cache.nodeFor("fd:rate"));

        // First read = DB miss, then cached
        log.info(() -> "read1 " + cache.read("balance:SAV2001"));
        log.info(() -> "read2 " + cache.read("balance:SAV2001")); // hit

        // Transfer changes Rajesh's balance → write-through + invalidate
        cache.writeThrough("balance:SAV2001", "950000");
        log.info(() -> "after write " + cache.read("balance:SAV2001")); // 950000, fresh

        // Stampede: hot key fd:rate expires, many concurrent reads
        cache.invalidate("fd:rate");
        Runnable reader = () -> log.info(() -> Thread.currentThread().getName()
            + " fd:rate=" + cache.readWithGuard("fd:rate"));
        Thread t1 = new Thread(reader, "T1"), t2 = new Thread(reader, "T2"), t3 = new Thread(reader, "T3");
        t1.start(); t2.start(); t3.start();
    }
}

