package com.bank.cache;

import java.util.*;

// Per-node LRU: evicts the least recently used entry when full.
public class LruCache {
    private final int capacity;
    private final LinkedHashMap<String,String> map;

    public LruCache(int capacity) {
        this.capacity = capacity;
        this.map = new LinkedHashMap<>(16, 0.75f, true) { // accessOrder=true
            protected boolean removeEldestEntry(Map.Entry<String,String> e) {
                return size() > LruCache.this.capacity;
            }
        };
    }
    public synchronized String get(String k) { return map.get(k); }
    public synchronized void put(String k, String v) { map.put(k, v); }
    public synchronized void remove(String k) { map.remove(k); }
}
